#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// TokenBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/token_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The characters that end an entry when typed or pasted, default ",;". Only ASCII punctuation and the space are admitted; anything else throws std::invalid_argument. Empty: only Enter ends an entry.
template <typename Declaring>
struct DelimitersCapability {
    PropertyCell<std::string, DelimitersCapability<Declaring>> delimiters{std::string{",;"}};

    static void assign(DelimitersCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.delimiters), incoming);
        if (!capability.delimiters.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.delimiters));
    }
};

// The editor's auto-complete (see TextBox); an accepted completion becomes a token. list_items throws std::invalid_argument.
template <typename Declaring>
struct TokenBoxAutoCompleteModeCapability {
    PropertyView<AutoCompleteMode, TokenBoxAutoCompleteModeCapability<Declaring>> auto_complete_mode;

    static void assign(TokenBoxAutoCompleteModeCapability& capability, AutoCompleteMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.auto_complete_mode), std::move(incoming));
    }

    static AutoCompleteMode read(const TokenBoxAutoCompleteModeCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        AutoCompleteMode current = control.read_view(capability.auto_complete_mode);
        return current;
    }
};

// Where the editor's completion candidates come from (see TextBox).
template <typename Declaring>
struct TokenBoxAutoCompleteSourceCapability {
    PropertyView<AutoCompleteSource, TokenBoxAutoCompleteSourceCapability<Declaring>> auto_complete_source;

    static void assign(TokenBoxAutoCompleteSourceCapability& capability, AutoCompleteSource incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.auto_complete_source), std::move(incoming));
    }

    static AutoCompleteSource read(const TokenBoxAutoCompleteSourceCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        AutoCompleteSource current = control.read_view(capability.auto_complete_source);
        return current;
    }
};

// The candidate list used when auto_complete_source is custom_source; null for none.
template <typename Declaring>
struct TokenBoxAutoCompleteCustomSourceCapability {
    PropertyView<std::shared_ptr<AutoCompleteStringCollection>, TokenBoxAutoCompleteCustomSourceCapability<Declaring>> auto_complete_custom_source;

    static void assign(TokenBoxAutoCompleteCustomSourceCapability& capability, std::shared_ptr<AutoCompleteStringCollection> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.auto_complete_custom_source), std::move(incoming));
    }

    static std::shared_ptr<AutoCompleteStringCollection> read(const TokenBoxAutoCompleteCustomSourceCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<AutoCompleteStringCollection> current = control.read_view(capability.auto_complete_custom_source);
        return current;
    }
};

// Every TokenBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct TokenBoxCapabilities : public DelimitersCapability<Declaring>,
                              public FontCapability<Declaring>,
                              public TokenBoxAutoCompleteModeCapability<Declaring>,
                              public TokenBoxAutoCompleteSourceCapability<Declaring>,
                              public TokenBoxAutoCompleteCustomSourceCapability<Declaring> {
    TokenBoxCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 12.0, 400, false}) {}
};

} // namespace gui_forms
